using ContosoUniversity.Data;
using Microsoft.EntityFrameworkCore;

namespace ContosoUniversity.Tests.Helpers;

public static class TestDbContextHelper
{
    public static SchoolContext CreateContext(string? dbName = null)
    {
        dbName ??= Guid.NewGuid().ToString();
        var options = new DbContextOptionsBuilder<SchoolContext>()
            .UseInMemoryDatabase(databaseName: dbName)
            .Options;
        return new SchoolContext(options);
    }
}

using ContosoUniversity.Models;

namespace ContosoUniversity.Tests.Models;

public class PersonTests
{
    // Concrete subclass to test abstract Person
    private class TestPerson : Person { }

    [Fact]
    public void FullName_ReturnsLastNameCommaFirstName()
    {
        // Arrange
        var person = new TestPerson { LastName = "Smith", FirstMidName = "John" };

        // Act
        var fullName = person.FullName;

        // Assert
        Assert.Equal("Smith, John", fullName);
    }

    [Fact]
    public void FullName_WithEmptyFirstName_ReturnsLastNameCommaEmpty()
    {
        var person = new TestPerson { LastName = "Doe", FirstMidName = "" };

        Assert.Equal("Doe, ", person.FullName);
    }

    [Fact]
    public void FullName_WithEmptyLastName_ReturnsCommaFirstName()
    {
        var person = new TestPerson { LastName = "", FirstMidName = "Jane" };

        Assert.Equal(", Jane", person.FullName);
    }

    [Theory]
    [InlineData("Alexander", "Carson", "Alexander, Carson")]
    [InlineData("O'Brien", "Mary", "O'Brien, Mary")]
    [InlineData("De La Cruz", "Ana Maria", "De La Cruz, Ana Maria")]
    public void FullName_VariousNames_ReturnsCorrectFormat(string lastName, string firstName, string expected)
    {
        var person = new TestPerson { LastName = lastName, FirstMidName = firstName };

        Assert.Equal(expected, person.FullName);
    }

    [Fact]
    public void Student_InheritsFromPerson_HasFullName()
    {
        var student = new Student { LastName = "Li", FirstMidName = "Yan", EnrollmentDate = DateTime.Today };

        Assert.Equal("Li, Yan", student.FullName);
        Assert.IsAssignableFrom<Person>(student);
    }

    [Fact]
    public void Instructor_InheritsFromPerson_HasFullName()
    {
        var instructor = new Instructor { LastName = "Kapoor", FirstMidName = "Candace", HireDate = DateTime.Today };

        Assert.Equal("Kapoor, Candace", instructor.FullName);
        Assert.IsAssignableFrom<Person>(instructor);
    }
}

using ContosoUniversity.Models;

namespace ContosoUniversity.Tests.Models;

public class ErrorViewModelTests
{
    [Fact]
    public void ShowRequestId_WhenRequestIdIsSet_ReturnsTrue()
    {
        var model = new ErrorViewModel { RequestId = "abc-123" };

        Assert.True(model.ShowRequestId);
    }

    [Fact]
    public void ShowRequestId_WhenRequestIdIsNull_ReturnsFalse()
    {
        var model = new ErrorViewModel { RequestId = null };

        Assert.False(model.ShowRequestId);
    }

    [Fact]
    public void ShowRequestId_WhenRequestIdIsEmpty_ReturnsFalse()
    {
        var model = new ErrorViewModel { RequestId = "" };

        Assert.False(model.ShowRequestId);
    }

    [Fact]
    public void ShowRequestId_WhenRequestIdIsWhitespace_ReturnsTrue()
    {
        // string.IsNullOrEmpty does not treat whitespace as empty
        var model = new ErrorViewModel { RequestId = "   " };

        Assert.True(model.ShowRequestId);
    }
}

