using ContosoUniversity.Models;
using ContosoUniversity.Services;

namespace ContosoUniversity.Tests.Services;

public class NotificationServiceTests : IDisposable
{
    private readonly NotificationService _sut;

    public NotificationServiceTests()
    {
        _sut = new NotificationService();
        // Drain the static queue to avoid cross-test interference
        while (_sut.ReceiveNotification() != null) { }
    }

    public void Dispose()
    {
        // Drain after test to clean up for next test
        while (_sut.ReceiveNotification() != null) { }
        _sut.Dispose();
    }

    [Fact]
    public void SendNotification_EnqueuesNotification_CanBeReceived()
    {
        _sut.SendNotification("Student", "1", EntityOperation.CREATE, "admin");

        var notification = _sut.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("Student", notification.EntityType);
        Assert.Equal("1", notification.EntityId);
        Assert.Equal("CREATE", notification.Operation);
        Assert.Equal("admin", notification.CreatedBy);
        Assert.False(notification.IsRead);
    }

    [Fact]
    public void SendNotification_WithDisplayName_GeneratesCorrectMessage()
    {
        _sut.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "admin");

        var notification = _sut.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("New Student 'John Doe' has been created", notification.Message);
    }

    [Fact]
    public void SendNotification_WithoutDisplayName_GeneratesIdBasedMessage()
    {
        _sut.SendNotification("Student", "42", EntityOperation.CREATE, "admin");

        var notification = _sut.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("New Student (ID: 42) has been created", notification.Message);
    }

    [Theory]
    [InlineData(EntityOperation.CREATE, "New Course 'Math' has been created")]
    [InlineData(EntityOperation.UPDATE, "Course 'Math' has been updated")]
    [InlineData(EntityOperation.DELETE, "Course 'Math' has been deleted")]
    public void SendNotification_DifferentOperations_GeneratesCorrectMessages(EntityOperation operation, string expectedMessage)
    {
        _sut.SendNotification("Course", "1", "Math", operation, "admin");

        var notification = _sut.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal(expectedMessage, notification.Message);
    }

    [Fact]
    public void SendNotification_WithNullUserName_DefaultsToSystem()
    {
        _sut.SendNotification("Student", "1", EntityOperation.CREATE, null);

        var notification = _sut.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("System", notification.CreatedBy);
    }

    [Fact]
    public void SendNotification_WithoutUserNameParameter_DefaultsToSystem()
    {
        _sut.SendNotification("Student", "1", EntityOperation.CREATE);

        var notification = _sut.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("System", notification.CreatedBy);
    }

    [Fact]
    public void ReceiveNotification_WhenEmpty_ReturnsNull()
    {
        var notification = _sut.ReceiveNotification();

        Assert.Null(notification);
    }

    [Fact]
    public void ReceiveNotification_DequeuesInOrder()
    {
        _sut.SendNotification("Student", "1", "First", EntityOperation.CREATE, "admin");
        _sut.SendNotification("Course", "2", "Second", EntityOperation.UPDATE, "admin");
        _sut.SendNotification("Department", "3", "Third", EntityOperation.DELETE, "admin");

        var first = _sut.ReceiveNotification();
        var second = _sut.ReceiveNotification();
        var third = _sut.ReceiveNotification();
        var fourth = _sut.ReceiveNotification();

        Assert.Equal("Student", first!.EntityType);
        Assert.Equal("Course", second!.EntityType);
        Assert.Equal("Department", third!.EntityType);
        Assert.Null(fourth);
    }

    [Fact]
    public void SendNotification_SetsCreatedAtToNonDefault()
    {
        var before = DateTime.Now.AddSeconds(-1);

        _sut.SendNotification("Student", "1", EntityOperation.CREATE, "admin");

        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.True(notification.CreatedAt >= before, $"CreatedAt {notification.CreatedAt} should be >= {before}");
        Assert.True(notification.CreatedAt <= DateTime.Now.AddSeconds(1));
    }

    [Fact]
    public void SendNotification_SetsIsReadToFalse()
    {
        _sut.SendNotification("Student", "1", EntityOperation.CREATE, "admin");

        var notification = _sut.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.False(notification.IsRead);
    }

    [Fact]
    public void MarkAsRead_DoesNotThrow()
    {
        var exception = Record.Exception(() => _sut.MarkAsRead(999));

        Assert.Null(exception);
    }

    [Fact]
    public void Dispose_DoesNotThrow()
    {
        var service = new NotificationService();

        var exception = Record.Exception(() => service.Dispose());

        Assert.Null(exception);
    }

    [Fact]
    public void SendNotification_QueueCap_DropsOldestWhenExceeded()
    {
        // Drain
        while (_sut.ReceiveNotification() != null) { }

        // Send 501 notifications
        for (int i = 0; i < 501; i++)
        {
            _sut.SendNotification("Entity", i.ToString(), $"Item{i}", EntityOperation.CREATE, "admin");
        }

        // Drain and count all remaining
        var received = new List<Notification>();
        Notification? n;
        while ((n = _sut.ReceiveNotification()) != null)
        {
            received.Add(n);
        }

        // Should have at most 500 (cap enforced)
        Assert.True(received.Count <= 500, $"Expected at most 500 notifications, got {received.Count}");
        // The very last one should be Item500 (most recent)
        var last = received[received.Count - 1];
        Assert.Equal("500", last.EntityId);
    }

    [Fact]
    public void SendNotification_OverloadWithoutDisplayName_Works()
    {
        _sut.SendNotification("Department", "5", EntityOperation.UPDATE, "user1");

        var notification = _sut.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Equal("Department", notification.EntityType);
        Assert.Equal("5", notification.EntityId);
        Assert.Equal("UPDATE", notification.Operation);
        Assert.Contains("Department (ID: 5)", notification.Message);
        Assert.Contains("updated", notification.Message);
    }

    [Fact]
    public void SendNotification_WithEmptyDisplayName_UsesIdBased()
    {
        _sut.SendNotification("Student", "7", "", EntityOperation.DELETE, "admin");

        var notification = _sut.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Contains("Student (ID: 7)", notification.Message);
    }

    [Fact]
    public void SendNotification_WithWhitespaceDisplayName_UsesIdBased()
    {
        _sut.SendNotification("Student", "7", "   ", EntityOperation.DELETE, "admin");

        var notification = _sut.ReceiveNotification();

        Assert.NotNull(notification);
        Assert.Contains("Student (ID: 7)", notification.Message);
    }
}

