using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;

namespace ContosoUniversity.Tests.Controllers;

public class NotificationsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly NotificationsController _controller;

    public NotificationsControllerTests()
    {
        _context = TestDbContextHelper.CreateContext();
        _controller = new NotificationsController(_context);
        // Drain the static notification queue before each test
        DrainNotificationQueue();
    }

    public void Dispose()
    {
        DrainNotificationQueue();
        _controller.Dispose();
        _context.Dispose();
    }

    private void DrainNotificationQueue()
    {
        // Access the notificationService field to drain the queue
        var service = new Services.NotificationService();
        while (service.ReceiveNotification() != null) { }
        service.Dispose();
    }

    [Fact]
    public void Index_ReturnsViewResult()
    {
        var result = _controller.Index();

        Assert.IsType<ViewResult>(result);
    }

    [Fact]
    public void GetNotifications_EmptyQueue_ReturnsSuccessWithZeroCount()
    {
        var result = _controller.GetNotifications();

        Assert.IsType<JsonResult>(result);
        var value = result.Value;
        Assert.NotNull(value);

        // Use reflection to check dynamic properties
        var type = value.GetType();
        var successProp = type.GetProperty("success");
        var countProp = type.GetProperty("count");
        Assert.NotNull(successProp);
        Assert.NotNull(countProp);
        Assert.True((bool)successProp.GetValue(value)!);
        Assert.Equal(0, (int)countProp.GetValue(value)!);
    }

    [Fact]
    public void GetNotifications_WithQueuedItems_ReturnsNotifications()
    {
        // Enqueue some notifications via the service
        var service = new Services.NotificationService();
        service.SendNotification("Student", "1", "John", EntityOperation.CREATE, "admin");
        service.SendNotification("Course", "2", "Math", EntityOperation.UPDATE, "admin");

        var result = _controller.GetNotifications();

        var type = result.Value!.GetType();
        var successProp = type.GetProperty("success");
        var countProp = type.GetProperty("count");
        Assert.True((bool)successProp!.GetValue(result.Value)!);
        Assert.Equal(2, (int)countProp!.GetValue(result.Value)!);

        service.Dispose();
    }

    [Fact]
    public void GetNotifications_LimitsTo10()
    {
        var service = new Services.NotificationService();
        for (int i = 0; i < 15; i++)
        {
            service.SendNotification("Entity", i.ToString(), EntityOperation.CREATE, "admin");
        }

        var result = _controller.GetNotifications();

        var type = result.Value!.GetType();
        var countProp = type.GetProperty("count");
        Assert.Equal(10, (int)countProp!.GetValue(result.Value)!);

        service.Dispose();
    }

    [Fact]
    public void MarkAsRead_ReturnsSuccessJson()
    {
        var result = _controller.MarkAsRead(1);

        Assert.IsType<JsonResult>(result);
        var type = result.Value!.GetType();
        var successProp = type.GetProperty("success");
        Assert.True((bool)successProp!.GetValue(result.Value)!);
    }
}

