using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.EntityFrameworkCore;

namespace ContosoUniversity.Tests.Data;

public class SchoolContextTests
{
    [Fact]
    public void SchoolContext_CanCreateAndQueryStudents()
    {
        using var context = TestDbContextHelper.CreateContext();
        context.Students.Add(new Student
        {
            FirstMidName = "Test",
            LastName = "Student",
            EnrollmentDate = new DateTime(2023, 9, 1)
        });
        context.SaveChanges();

        var student = context.Students.First();
        Assert.Equal("Test", student.FirstMidName);
        Assert.Equal("Student", student.LastName);
    }

    [Fact]
    public void SchoolContext_CanCreateAndQueryCourses()
    {
        using var context = TestDbContextHelper.CreateContext();
        var dept = new Department
        {
            Name = "Test Dept",
            Budget = 100000,
            StartDate = new DateTime(2007, 9, 1)
        };
        context.Departments.Add(dept);
        context.SaveChanges();

        context.Courses.Add(new Course
        {
            CourseID = 1001,
            Title = "Test Course",
            Credits = 3,
            DepartmentID = dept.DepartmentID
        });
        context.SaveChanges();

        var course = context.Courses.Include(c => c.Department).First();
        Assert.Equal("Test Course", course.Title);
        Assert.Equal("Test Dept", course.Department.Name);
    }

    [Fact]
    public void SchoolContext_CourseAssignment_HasCompositeKey()
    {
        using var context = TestDbContextHelper.CreateContext();

        var instructor = new Instructor
        {
            FirstMidName = "Test",
            LastName = "Instructor",
            HireDate = new DateTime(2000, 1, 1),
            CourseAssignments = new List<CourseAssignment>()
        };
        context.Instructors.Add(instructor);
        context.SaveChanges();

        var dept = new Department
        {
            Name = "Dept",
            Budget = 100000,
            StartDate = DateTime.Today
        };
        context.Departments.Add(dept);
        context.SaveChanges();

        var course = new Course
        {
            CourseID = 5000,
            Title = "Course",
            Credits = 3,
            DepartmentID = dept.DepartmentID,
            CourseAssignments = new List<CourseAssignment>()
        };
        context.Courses.Add(course);
        context.SaveChanges();

        var assignment = new CourseAssignment
        {
            InstructorID = instructor.ID,
            CourseID = course.CourseID
        };
        context.CourseAssignments.Add(assignment);
        context.SaveChanges();

        var found = context.CourseAssignments.Find(course.CourseID, instructor.ID);
        Assert.NotNull(found);
        Assert.Equal(instructor.ID, found.InstructorID);
        Assert.Equal(course.CourseID, found.CourseID);
    }

    [Fact]
    public void SchoolContext_TPH_StudentAndInstructorSharePersonTable()
    {
        using var context = TestDbContextHelper.CreateContext();

        context.Students.Add(new Student
        {
            FirstMidName = "StudentFirst",
            LastName = "StudentLast",
            EnrollmentDate = DateTime.Today
        });
        context.Instructors.Add(new Instructor
        {
            FirstMidName = "InstructorFirst",
            LastName = "InstructorLast",
            HireDate = DateTime.Today,
            CourseAssignments = new List<CourseAssignment>()
        });
        context.SaveChanges();

        // Both should be queryable through People
        var people = context.Set<Person>().ToList();
        Assert.Equal(2, people.Count);
        Assert.Contains(people, p => p is Student);
        Assert.Contains(people, p => p is Instructor);
    }

    [Fact]
    public void SchoolContext_OfficeAssignment_OneToOneWithInstructor()
    {
        using var context = TestDbContextHelper.CreateContext();

        var instructor = new Instructor
        {
            FirstMidName = "Test",
            LastName = "Inst",
            HireDate = DateTime.Today,
            CourseAssignments = new List<CourseAssignment>()
        };
        context.Instructors.Add(instructor);
        context.SaveChanges();

        context.OfficeAssignments.Add(new OfficeAssignment
        {
            InstructorID = instructor.ID,
            Location = "Room 42"
        });
        context.SaveChanges();

        var oa = context.OfficeAssignments.Include(o => o.Instructor).Single();
        Assert.Equal("Room 42", oa.Location);
        Assert.Equal(instructor.ID, oa.InstructorID);
        Assert.Equal("Test", oa.Instructor.FirstMidName);
    }

    [Fact]
    public void SchoolContext_Enrollment_LinksStudentAndCourse()
    {
        using var context = TestDbContextHelper.CreateContext();

        var student = new Student
        {
            FirstMidName = "S",
            LastName = "Stu",
            EnrollmentDate = DateTime.Today
        };
        context.Students.Add(student);

        var dept = new Department { Name = "D", Budget = 100, StartDate = DateTime.Today };
        context.Departments.Add(dept);
        context.SaveChanges();

        var course = new Course
        {
            CourseID = 9999,
            Title = "C",
            Credits = 1,
            DepartmentID = dept.DepartmentID
        };
        context.Courses.Add(course);
        context.SaveChanges();

        context.Enrollments.Add(new Enrollment
        {
            StudentID = student.ID,
            CourseID = course.CourseID,
            Grade = Grade.A
        });
        context.SaveChanges();

        var enrollment = context.Enrollments
            .Include(e => e.Student)
            .Include(e => e.Course)
            .Single();

        Assert.Equal(student.ID, enrollment.StudentID);
        Assert.Equal(course.CourseID, enrollment.CourseID);
        Assert.Equal(Grade.A, enrollment.Grade);
        Assert.Equal("S", enrollment.Student.FirstMidName);
        Assert.Equal("C", enrollment.Course.Title);
    }

    [Fact]
    public void SchoolContext_Notification_CanBeCreatedAndQueried()
    {
        using var context = TestDbContextHelper.CreateContext();

        context.Notifications.Add(new Notification
        {
            EntityType = "Student",
            EntityId = "1",
            Operation = "CREATE",
            Message = "Test notification",
            CreatedAt = DateTime.Now,
            CreatedBy = "admin",
            IsRead = false
        });
        context.SaveChanges();

        var notification = context.Notifications.Single();
        Assert.Equal("Student", notification.EntityType);
        Assert.Equal("CREATE", notification.Operation);
        Assert.Equal("Test notification", notification.Message);
        Assert.False(notification.IsRead);
    }
}

