    [Fact]
    public void Constructor_SetsPageIndexAndTotalPages()
    {
        var items = new List<string> { "a", "b", "c" };

        var list = new PaginatedList<string>(items, count: 15, pageIndex: 2, pageSize: 5);

        Assert.Equal(2, list.PageIndex);
        Assert.Equal(3, list.TotalPages);
        Assert.Equal(3, list.Count);
        Assert.Equal("a", list[0]);
        Assert.Equal("c", list[2]);
    }

    [Fact]
    public void HasPreviousPage_ExactlyPage1_ReturnsFalse()
    {
        // Mutation guard: PageIndex > 1 should be false when PageIndex is exactly 1
        // If mutated to >= 1, this would wrongly return true
        var list = new PaginatedList<int>(new List<int> { 1 }, count: 10, pageIndex: 1, pageSize: 5);

        Assert.Equal(1, list.PageIndex);
        Assert.False(list.HasPreviousPage);
    }

    [Fact]
    public void HasNextPage_ExactlyLastPage_ReturnsFalse()
    {
        // Mutation guard: PageIndex < TotalPages should be false when PageIndex equals TotalPages
        // If mutated to <= TotalPages, this would wrongly return true
        var list = new PaginatedList<int>(new List<int> { 1 }, count: 10, pageIndex: 2, pageSize: 5);

        Assert.Equal(2, list.PageIndex);
        Assert.Equal(2, list.TotalPages);
        Assert.False(list.HasNextPage);
    }

    [Fact]
    public void Create_PageIndex1_SkipsZeroItems()
    {
        // Mutation guard: Skip((pageIndex - 1) * pageSize) should skip 0 items when pageIndex=1
        var source = new[] { 10, 20, 30, 40, 50 }.AsQueryable();

        var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 3);

        Assert.Equal(3, result.Count);
        Assert.Equal(10, result[0]); // First item must be the first source element
        Assert.Equal(30, result[2]); // Third item
    }

    [Fact]
    public void Create_PageIndex2_SkipsFirstPage()
    {
        // Validates skip calculation: should skip exactly pageSize items
        var source = new[] { 10, 20, 30, 40, 50 }.AsQueryable();

        var result = PaginatedList<int>.Create(source, pageIndex: 2, pageSize: 3);

        Assert.Equal(2, result.Count);
        Assert.Equal(40, result[0]); // Should start from 4th element
        Assert.Equal(50, result[1]);
    }

    [Fact]
    public void TotalPages_SingleItem_IsOne()
    {
        var source = new[] { 42 }.AsQueryable();

        var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

        Assert.Equal(1, result.TotalPages);
        Assert.Single(result);
        Assert.Equal(42, result[0]);
    }
}

